}

.analysis-popup .custom-modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 90%;
  background: #fff;
  border-radius: 12rpx;
  z-index: 100002;
  max-height: 70vh;
  overflow: hidden;
  pointer-events: auto;

  .modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16rpx 20rpx;
    border-bottom: 1rpx solid #eee;

